// Registers generated by the nested svd_converter from its golden fixture (svd_converter/tests/golden/features.svd)
// against src/kvasir/Register: every register, instance, group element and dim element is instantiated by the
// instantiate_all.py TU built next to this one (a static_assert in a generated register is only evaluated when the
// register is instantiated), and here the generated masks meet the Register layer through the mock.
// Addresses and masks below are the fixture's (features.svd); a fixture change changes them here too.
#include "fixture_plain/CTRLP.hpp"
#include "fixture_plain/INHERIT.hpp"
#include "fixture_plain/InterruptNames.hpp"
#include "fixture_plain/SERCOM_SPI.hpp"
#include "fixture_plain/SERCOM_UART.hpp"
#include "fixture_plain/SPARE.hpp"
#include "fixture_plain/TC.hpp"
#include "kvasir_test.hpp"

#include <array>
#include <cstdint>
#include <type_traits>

using namespace Kvasir::Register;
using namespace Kvasir::Test;

namespace {
using P    = Kvasir::Peripheral::CTRLP::Registers<>;
using CTRL = P::CTRL;

constexpr unsigned base = 0x40000000U;

template<typename F>
using AccessOf = typename std::remove_cvref_t<F>::Access;

// --- what the converter emits, checked at compile time --------------------------------------------------------------

static_assert(RegisterTraits<CTRL::Addr>::address == base);
static_assert(RegisterTraits<P::INTFLAG::Addr>::address == base + 0x04);
static_assert(std::is_same_v<P::INTFLAG::Addr::RegType,
                             std::uint8_t>,
              "INTFLAG is an 8-bit register");
static_assert(std::is_same_v<P::TRIGGER::Addr::RegType,
                             std::uint16_t>,
              "TRIGGER is a 16-bit register");
static_assert(RegisterTraits<P::KEYREG::Addr>::mustSupplyMask == 0xFFFF0000U,
              "KEY is a key field");
static_assert(RegisterTraits<P::FIFO::Addr>::readHasSideEffect,
              "FIFO's read pops");
static_assert(RegisterTraits<P::STROBE::Addr>::writeOnlyRegister,
              "STROBE has no readable field");
static_assert(RegisterTraits<P::INTFLAG::Addr>::writeBackActsMask == 0x03U,
              "the W1C flags");
static_assert(RegisterTraits<P::TRIGGER::Addr>::writeIgnoredIfOneMask == 0x0004U,
              "DONE is zero-to-clear");
// the accepted write-only strobe is no hazard: no writeOnlyNoIdentity bit in its Mode
static_assert(RegisterTraits<CTRL::Addr>::writeOnlyNoIdentityMask == 0U);
static_assert(RegisterTraits<P::CH<3>::Addr>::address == base + 0x20 + 3 * 4,
              "dim register element");
static_assert(decltype(P::CH<1>::EN<1>::en)::mask == (1U << 9),
              "dim field element in a dim register");
static_assert(decltype(P::PINS::IN<3>::in)::mask == (0x3U << 6),
              "dim field element");
static_assert(RegisterTraits<P::GRP<1>::CFG::Addr>::address == base + 0x40 + 0x10,
              "group element");
// fieldAt<Bit>(R{}): the generated field holding the bit - a dim field's element, a plain field, with its access
static_assert(std::is_same_v<decltype(fieldAt<4>(P::PINS{})),
                             std::remove_cvref_t<decltype(P::PINS::IN<2>::in)>>);
static_assert(std::is_same_v<FieldAt<P::PINS,
                                     7>,
                             std::remove_cvref_t<decltype(P::PINS::IN<3>::in)>>);
static_assert(std::is_same_v<FieldAt<P::INTFLAG,
                                     1>,
                             std::remove_cvref_t<decltype(P::INTFLAG::error)>>,
              "the W1C flag with its one-to-clear access, field type std::uint8_t");
// the group's own register GRP is GRP_ (a member named like its class is no C++)
static_assert(RegisterTraits<P::GRP<1>::GRP_::Addr>::address == base + 0x40 + 0x10 + 0x4);
static_assert(RegisterTraits<Kvasir::Peripheral::TC::Registers<0>::COUNT::Addr>::address
              == 0x40001000U);
static_assert(RegisterTraits<Kvasir::Peripheral::TC::Registers<1>::COUNT::Addr>::address
                == 0x40001400U,
              "the derived peripheral TC1 is instance 1");
static_assert(RegisterTraits<Kvasir::Peripheral::SERCOM_SPI::Registers<>::CTRLA::Addr>::address
                == 0x40002000U,
              "a mode cluster is a peripheral of its own");
// one name per vector: TC0 and TC1 share vector 1
static_assert(Kvasir::Peripheral::interruptNames.size() == 4);
static_assert(Kvasir::Peripheral::interruptNames[1].index == 1
              && Kvasir::Peripheral::interruptNames[1].name == "TC");
// the generated header specialises Startup's names hook (StartUp/InterruptNames.hpp) from the same array
static_assert(Kvasir::Startup::Diagnostics::DeviceInterruptNames<Kvasir::Tag::User>::of(1) == "TC");
static_assert(Kvasir::Startup::Diagnostics::DeviceInterruptNames<Kvasir::Tag::User>::of(2).empty(),
              "a gap");
static_assert(Kvasir::Startup::Diagnostics::interruptName<struct AnyRule>(3) == "SERCOM");

// register properties pass down device -> peripheral -> cluster -> register; derivedFrom names the SVD <name>;
// a writable field outside <resetMask> has no reset value, so its register has no overrideDefaults
using I = Kvasir::Peripheral::INHERIT::Registers<>;
static_assert(std::is_same_v<I::STATUS::Addr::RegType,
                             std::uint16_t>,
              "STATUS inherits the peripheral's size");
static_assert(std::is_same_v<AccessOf<decltype(I::STATUS::level)>,
                             ReadOnlyAccess>,
              "and its access (read-only)");
static_assert(RegisterTraits<I::CTRLB::Addr>::address == 0x40003004U,
              "CTRL_B derives from CTRL_A (displayName CTRLA) by its SVD name");
static_assert(std::is_same_v<I::LANE_CFG<1>::SEL::Addr::RegType,
                             std::uint8_t>
                && RegisterTraits<I::LANE_CFG<1>::SEL::Addr>::address == 0x40003011U,
              "a dim cluster's own size; LANE.CFG[%s] sanitized to LANE_CFG");
template<typename R>
concept HasDefaults = requires { R::overrideDefaults(); };
static_assert(!HasDefaults<I::DIV>,
              "DIV's MODE lies outside resetMask 0");
static_assert(HasDefaults<I::PART>,
              "PART's MODE has its defined bit in resetMask");
// FULLREGISTER's access: a field-less register's own <access> (inherited; writeOnce is write-only), write-only when no
// field can be read
static_assert(std::is_same_v<AccessOf<decltype(I::ID::FULLREGISTER)>,
                             ReadOnlyAccess>,
              "ID inherits read-only");
static_assert(std::is_same_v<AccessOf<decltype(I::TXDATA::FULLREGISTER)>,
                             WriteOnlyAccess>);
static_assert(std::is_same_v<AccessOf<decltype(I::ONCE::FULLREGISTER)>,
                             WriteOnlyAccess>,
              "writeOnce");
static_assert(std::is_same_v<AccessOf<decltype(P::STROBE::FULLREGISTER)>,
                             WriteOnlyAccess>,
              "STROBE: no field can be read");
static_assert(std::is_same_v<AccessOf<decltype(P::BUF::FULLREGISTER)>,
                             ReadWriteAccess>,
              "BUF: field-less, the device's read-write");

}   // namespace

// A peripheral without registers (SPARE, interrupt only, base address 0) has no Registers<>: qualified lookup
// finds a Registers declared in SPARE itself first, the stand-in of the using-directive only when there is none.
namespace AbsentRegisters {
template<unsigned = 0>
struct Registers {
    static constexpr bool absent = true;
};
}   // namespace AbsentRegisters

namespace Kvasir::Peripheral::SPARE {
using namespace ::AbsentRegisters;
}   // namespace Kvasir::Peripheral::SPARE

static_assert(Kvasir::Peripheral::SPARE::Registers<>::absent,
              "SPARE has no Registers<>");

namespace {

// The identity cross-check: the converter's identityOf (svd/semantics.hpp) decided IDENT's masks, the SDK's
// identityOf decides what the Register layer expects. One literal row per IDENT field of features.svd.
using AT = AccessType;
using M  = ModifiedWriteValueType;

struct Row {
    AT at;
    M  m;
};

constexpr std::array rows{
  Row{AT::readWrite,       M::normal}, // RW_PLAIN
  Row{AT::readWrite,   M::oneToClear}, // RW_ONETOCLEAR
  Row{AT::readWrite,     M::oneToSet}, // RW_ONETOSET
  Row{AT::readWrite,  M::oneToToggle}, // RW_ONETOTOGGLE
  Row{AT::readWrite,  M::zeroToClear}, // RW_ZEROTOCLEAR
  Row{AT::readWrite,    M::zeroToSet}, // RW_ZEROTOSET
  Row{AT::readWrite, M::zeroToToggle}, // RW_ZEROTOTOGGLE
  Row{AT::readWrite,        M::clear}, // RW_CLEAR
  Row{AT::readWrite,          M::set}, // RW_SET
  Row{AT::readWrite,       M::modify}, // RW_MODIFY
  Row{ AT::readOnly,       M::normal}, // RO
  Row{AT::writeOnly,     M::oneToSet}, // WO_ONETOSET
  Row{AT::writeOnly,  M::zeroToClear}, // WO_ZEROTOCLEAR
  Row{AT::writeOnly,       M::normal}, // WO_PLAIN
};
static_assert(fieldMasks<P::IDENT>.size() == rows.size(),
              "one row per IDENT field");

constexpr auto identities = [] {
    std::array<Identity, rows.size()> ids{};
    for(std::size_t i = 0; i < rows.size(); ++i) { ids[i] = identityOf(rows[i].at, rows[i].m); }
    return ids;
}();
static_assert(masksMatchFields<P::IDENT::Addr>(fieldMasks<P::IDENT>,
                                               identities),
              "the converter's masks and the SDK's identityOf disagree");
// and the access each field was generated with says the same
static_assert(identityOfAccess<AccessOf<decltype(P::IDENT::rw_onetoclear)>> == identities[1]);
static_assert(identityOfAccess<AccessOf<decltype(P::IDENT::rw_zerototoggle)>> == identities[6]);
static_assert(identityOfAccess<AccessOf<decltype(P::IDENT::wo_onetoset)>> == identities[11]);

// --- what the writes do --------------------------------------------------------------------------------------------

void plainFieldWrite() {
    test("write() of a plain field: one read, one write, the other fields as read");
    recorder.setReadValue(base + 0x20, 0x3FFU);
    apply(write(P::CH<0>::threshold, value<std::uint32_t, 0x5AU>()));
    checkActions({
      R{base + 0x20,                    0x3FFU},
      W{base + 0x20, (0x3FFU & ~0xFFU) | 0x5AU}
    });
}

void enumWrite() {
    test("write() of an enum value");
    recorder.setReadValue(base, 0x00000001U);
    apply(write(CTRL::MODEValC::fast));
    checkActions({
      R{base, 0x00000001U},
      W{base, 0x00000005U}
    });
}

void flagClear() {
    test("set() of a W1C flag next to a pending one: one store, the other flag written 0");
    apply(set(P::INTFLAG::ready));
    checkActions({
      W{base + 0x04, 0x01U}
    });
}

void zeroToClearKept() {
    test(
      "a field write next to triggers and a zero-to-clear flag: one store, triggers 0, the flag 1");
    apply(write(P::TRIGGER::level, value<std::uint16_t, 5U>()));
    checkActions({
      W{base + 0x08, 0x0504U}
    });
}

void keyWrite() {
    test(
      "a key register write that names its key: one store (the field VALUE is generated as "
      "_value)");
    apply(write(P::KEYREG::key, value<std::uint32_t, 0x5AFEU>()),
          write(P::KEYREG::_value, value<std::uint32_t, 0x12U>()));
    checkActions({
      W{base + 0x0C, 0x5AFE0012U}
    });
}

void writeOnlyRegister() {
    test("a write-only register: a partial write never reads");
    apply(set(P::STROBE::go));
    checkActions({
      W{base + 0x14, 0x1U}
    });
}

void sideEffectRead() {
    test("a read of the popping FIFO: one read");
    recorder.setReadValue(base + 0x10, 0xCAFEU);
    auto const v = apply(read(P::FIFO::data));
    CHECK_EQ(v, 0xCAFEU);
    checkActions({
      R{base + 0x10, 0xCAFEU}
    });
}

void defaults() {
    test("overrideDefaults(): the reset value with the override, one store");
    apply(CTRL::overrideDefaults(set(CTRL::enable)));
    checkActions({
      W{base, 0x00000003U}
    });
}

void acceptedWriteOnlyNamed() {
    test("naming the accepted write-only strobe: its bit in the store");
    recorder.setReadValue(base, 0x00000002U);
    apply(set(CTRL::swrst), set(CTRL::enable));
    checkActions({
      R{base,         0x00000002U},
      W{base, 0x00000002U | 0x11U}
    });
}

void dimAndGroupElements() {
    test("a dim register element, a dim field element and a group element at their addresses");
    recorder.setReadValue(base + 0x24, 0x0U);
    apply(set(P::CH<1>::EN<1>::en));
    apply(write(P::GRP<1>::GRP_::evt, value<std::uint32_t, 0x7U>()));
    apply(
      write(Kvasir::Peripheral::TC::Registers<1>::COUNT::count, value<std::uint16_t, 0x1234U>()));
    checkActions({
      R{base + 0x24,    0x0U},
      W{base + 0x24, 1U << 9},
      W{base + 0x54,    0x7U},
      W{0x40001400U, 0x1234U}
    });
}
}   // namespace

int main() {
    plainFieldWrite();
    enumWrite();
    flagClear();
    zeroToClearKept();
    keyWrite();
    writeOnlyRegister();
    sideEffectRead();
    defaults();
    acceptedWriteOnlyNamed();
    dimAndGroupElements();
    return Kvasir::Test::report();
}
